import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";

const SellerApplyForReels = ({ onClose }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    mobile: "",
    companyName: "",
    companyWebsite: "",
    instagramHandle: "",
    facebookPage: "",
    experience: "",
    categories: "",
    message: ""
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [showPasswordForm, setShowPasswordForm] = useState(false);
  const [passwordData, setPasswordData] = useState({
    password: "",
    confirmPassword: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handlePasswordChange = (e) => {
    setPasswordData({
      ...passwordData,
      [e.target.name]: e.target.value
    });
  };

  const validateForm = () => {
    if (!formData.firstName) {
      setError("First name is required");
      return false;
    }
    
    if (!formData.lastName) {
      setError("Last name is required");
      return false;
    }
    
    if (!formData.email) {
      setError("Email is required");
      return false;
    }
    
    if (!formData.mobile) {
      setError("Mobile number is required");
      return false;
    }
    
    if (!formData.companyName) {
      setError("Company name is required");
      return false;
    }
    
    if (!formData.experience) {
      setError("Experience is required");
      return false;
    }
    
    if (!formData.categories) {
      setError("Product categories are required");
      return false;
    }
    
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    setLoading(true);
    setError("");
    
    try {
      // First, check if seller exists in oc_vendor table
      const vendorCheckResponse = await fetch('http://localhost:3188/Studio/seller/check-vendor', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          email: formData.email,
          mobile: formData.mobile
        })
      });
      
      const vendorCheckData = await vendorCheckResponse.json();
      
      if (!vendorCheckData.exists) {
        setError("You are not a seller of IP Shopy. Please first register as a seller.");
        setLoading(false);
        return;
      }
      
      // If seller exists, show password form
      setShowPasswordForm(true);
    } catch (error) {
      setError("Failed to verify seller information. Please try again.");
      setLoading(false);
    }
  };

  const handlePasswordSubmit = async (e) => {
    e.preventDefault();
    
    if (!passwordData.password) {
      setError("Password is required");
      return;
    }
    
    if (passwordData.password !== passwordData.confirmPassword) {
      setError("Passwords do not match");
      return;
    }
    
    if (passwordData.password.length < 6) {
      setError("Password must be at least 6 characters long");
      return;
    }
    
    setLoading(true);
    setError("");
    
    try {
      // Register seller with password
      const response = await fetch('http://localhost:3188/Studio/seller/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          password: passwordData.password
        })
      });
      
      const data = await response.json();
      
      if (data.success) {
        setSuccess(true);
        toast.success("Registration successful! You can now login.");
        
        // Wait 3 seconds then switch to login view
        setTimeout(() => {
          if (onClose) {
            onClose();
            window.dispatchEvent(new CustomEvent('openLoginModal', { detail: 'seller-login' }));
          }
        }, 3000);
      } else {
        setError(data.message || "Registration failed. Please try again.");
      }
    } catch (error) {
      setError("Registration failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  if (showPasswordForm) {
    return (
      <div className="container-fluid">
        <div className="row justify-content-center">
          <div className="col-12">
            {error && (
              <div className="alert alert-danger alert-dismissible fade show" role="alert">
                {error}
                <button 
                  type="button" 
                  className="btn-close" 
                  data-bs-dismiss="alert" 
                  aria-label="Close"
                  onClick={() => setError("")}
                ></button>
              </div>
            )}
            
            {success && (
              <div className="alert alert-success alert-dismissible fade show" role="alert">
                Registration successful! Redirecting to login page...
                <button 
                  type="button" 
                  className="btn-close" 
                  data-bs-dismiss="alert" 
                  aria-label="Close"
                  onClick={() => setSuccess(false)}
                ></button>
              </div>
            )}
            
            <div className="text-center mb-3">
              <h5 className="fw-bold text-dark">Set Password</h5>
              <p className="text-muted small">Create a password for your account</p>
            </div>
            
            <form onSubmit={handlePasswordSubmit} className="mt-3">
              <div className="mb-3">
                <label htmlFor="password" className="form-label">
                  <i className="fas fa-lock me-2"></i>Password *
                </label>
                <div className="position-relative">
                  <input
                    type="password"
                    className="form-control form-control-lg"
                    id="password"
                    name="password"
                    placeholder="Enter your password"
                    value={passwordData.password}
                    onChange={handlePasswordChange}
                    required
                    disabled={loading}
                  />
                </div>
              </div>
              
              <div className="mb-4">
                <label htmlFor="confirmPassword" className="form-label">
                  <i className="fas fa-lock me-2"></i>Confirm Password *
                </label>
                <div className="position-relative">
                  <input
                    type="password"
                    className="form-control form-control-lg"
                    id="confirmPassword"
                    name="confirmPassword"
                    placeholder="Confirm your password"
                    value={passwordData.confirmPassword}
                    onChange={handlePasswordChange}
                    required
                    disabled={loading}
                  />
                </div>
              </div>

              <div className="d-flex justify-content-between">
                <button
                  type="button"
                  className="btn btn-outline-secondary"
                  onClick={() => setShowPasswordForm(false)}
                  disabled={loading}
                >
                  Back
                </button>
                <button
                  className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium"
                  type="submit"
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                      Setting Password...
                    </>
                  ) : (
                    <>
                      <i className="fas fa-check-circle me-2"></i>Complete Registration
                    </>
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container-fluid">
      <div className="row justify-content-center">
        <div className="col-12">
          {error && (
            <div className="alert alert-danger alert-dismissible fade show" role="alert">
              {error}
              <button 
                type="button" 
                className="btn-close" 
                data-bs-dismiss="alert" 
                aria-label="Close"
                onClick={() => setError("")}
              ></button>
            </div>
          )}
          
          {success && (
            <div className="alert alert-success alert-dismissible fade show" role="alert">
              Application submitted successfully! Redirecting to login page...
              <button 
                type="button" 
                className="btn-close" 
                data-bs-dismiss="alert" 
                aria-label="Close"
                onClick={() => setSuccess(false)}
              ></button>
            </div>
          )}
          
          <div className="text-center mb-3">
            <h5 className="fw-bold text-dark">Apply for Seller Reels</h5>
            <p className="text-muted small">Fill in your details to get started</p>
          </div>
          
          <form onSubmit={handleSubmit} className="mt-3">
            <div className="row">
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="firstName" className="form-label">
                    <i className="fas fa-user me-2"></i>First Name *
                  </label>
                  <input
                    type="text"
                    className="form-control form-control-lg"
                    id="firstName"
                    name="firstName"
                    value={formData.firstName}
                    onChange={handleChange}
                    required
                    placeholder="Enter your first name"
                  />
                </div>
              </div>
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="lastName" className="form-label">
                    <i className="fas fa-user me-2"></i>Last Name *
                  </label>
                  <input
                    type="text"
                    className="form-control form-control-lg"
                    id="lastName"
                    name="lastName"
                    value={formData.lastName}
                    onChange={handleChange}
                    required
                    placeholder="Enter your last name"
                  />
                </div>
              </div>
            </div>

            <div className="row">
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="email" className="form-label">
                    <i className="fas fa-envelope me-2"></i>Email Address *
                  </label>
                  <input
                    type="email"
                    className="form-control form-control-lg"
                    id="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    required
                    placeholder="Enter your email"
                  />
                </div>
              </div>
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="mobile" className="form-label">
                    <i className="fas fa-mobile-alt me-2"></i>Mobile Number *
                  </label>
                  <input
                    type="tel"
                    className="form-control form-control-lg"
                    id="mobile"
                    name="mobile"
                    value={formData.mobile}
                    onChange={handleChange}
                    required
                    placeholder="Enter your mobile number"
                  />
                </div>
              </div>
            </div>

            <div className="row">
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="companyName" className="form-label">
                    <i className="fas fa-building me-2"></i>Company Name *
                  </label>
                  <input
                    type="text"
                    className="form-control form-control-lg"
                    id="companyName"
                    name="companyName"
                    value={formData.companyName}
                    onChange={handleChange}
                    required
                    placeholder="Enter your company name"
                  />
                </div>
              </div>
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="companyWebsite" className="form-label">
                    <i className="fas fa-globe me-2"></i>Company Website
                  </label>
                  <input
                    type="url"
                    className="form-control form-control-lg"
                    id="companyWebsite"
                    name="companyWebsite"
                    value={formData.companyWebsite}
                    onChange={handleChange}
                    placeholder="https://example.com"
                  />
                </div>
              </div>
            </div>

            <div className="row">
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="instagramHandle" className="form-label">
                    <i className="fab fa-instagram me-2"></i>Instagram Handle
                  </label>
                  <input
                    type="text"
                    className="form-control form-control-lg"
                    id="instagramHandle"
                    name="instagramHandle"
                    value={formData.instagramHandle}
                    onChange={handleChange}
                    placeholder="@username"
                  />
                </div>
              </div>
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="facebookPage" className="form-label">
                    <i className="fab fa-facebook me-2"></i>Facebook Page
                  </label>
                  <input
                    type="text"
                    className="form-control form-control-lg"
                    id="facebookPage"
                    name="facebookPage"
                    value={formData.facebookPage}
                    onChange={handleChange}
                    placeholder="https://facebook.com/page"
                  />
                </div>
              </div>
            </div>

            <div className="row">
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="experience" className="form-label">
                    <i className="fas fa-briefcase me-2"></i>Years of Experience *
                  </label>
                  <select
                    className="form-select form-select-lg"
                    id="experience"
                    name="experience"
                    value={formData.experience}
                    onChange={handleChange}
                    required
                  >
                    <option value="">Select experience</option>
                    <option value="0-1">0-1 years</option>
                    <option value="1-3">1-3 years</option>
                    <option value="3-5">3-5 years</option>
                    <option value="5+">5+ years</option>
                  </select>
                </div>
              </div>
              <div className="col-md-6">
                <div className="mb-3">
                  <label htmlFor="categories" className="form-label">
                    <i className="fas fa-tags me-2"></i>Product Categories *
                  </label>
                  <input
                    type="text"
                    className="form-control form-control-lg"
                    id="categories"
                    name="categories"
                    value={formData.categories}
                    onChange={handleChange}
                    required
                    placeholder="e.g., Electronics, Fashion, Home Decor"
                  />
                </div>
              </div>
            </div>

            <div className="mb-4">
              <label htmlFor="message" className="form-label">
                <i className="fas fa-comment me-2"></i>Why do you want to join our platform?
              </label>
              <textarea
                className="form-control form-control-lg"
                id="message"
                name="message"
                rows="4"
                placeholder="Tell us about your business and goals"
                value={formData.message}
                onChange={handleChange}
              ></textarea>
            </div>

            <div className="d-flex justify-content-between">
              <button
                type="button"
                className="btn btn-outline-secondary"
                onClick={onClose}
                disabled={loading}
              >
                Cancel
              </button>
              <button
                className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium"
                type="submit"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    Verifying...
                  </>
                ) : (
                  <>
                    <i className="fas fa-paper-plane me-2"></i>Verify & Continue
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default SellerApplyForReels;
